  1	import { MoveLeadToStage } from '../../src/application/use-cases/MoveLeadToStage';
  2	import { InvalidPhoneNumberError } from '../../src/domain/errors/InvalidPhoneNumberError';
  3	import { InvalidStageTransitionError } from '../../src/domain/errors/InvalidStageTransitionError';
  4	import { LeadNotFoundError } from '../../src/domain/errors/LeadNotFoundError';
  5	import { StageCapacityExceededError } from '../../src/domain/errors/StageCapacityExceededError';
  6	import { StageNotFoundError } from '../../src/domain/errors/StageNotFoundError';
  7	import { FakeLeadRepository } from '../helpers/FakeLeadRepository';
  8	import {
  9	  ANOTHER_PHONE,
 10	  A_PHONE,
 11	  CLOSED,
 12	  CONTACTED,
 13	  NEW,
 14	  QUALIFIED,
 15	  funnelWith,
 16	  lead,
 17	} from '../helpers/factories';
 18	
 19	/**
 20	 * The precedence under test is not derived here. It is quoted from MAP.md §4:
 21	 *
 22	 *   entrada valida (PhoneNumber)        -> InvalidPhoneNumberError
 23	 *     -> etapa destino existe           -> StageNotFoundError
 24	 *     -> lead existe                    -> LeadNotFoundError
 25	 *     -> destino != actual              -> InvalidStageTransitionError
 26	 *     -> cupo en destino                -> StageCapacityExceededError
 27	 *     -> moveTo + save
 28	 */
 29	describe('MoveLeadToStage', () => {
 30	  describe('a valid move', () => {
 31	    it('moves the lead to the target stage and saves it', async () => {
 32	      const ada = lead(A_PHONE, NEW);
 33	      const repository = FakeLeadRepository.seededWith(ada);
 34	      const useCase = new MoveLeadToStage(repository, funnelWith());
 35	
 36	      await useCase.execute({ phone: A_PHONE, targetStageId: CONTACTED });
 37	
 38	      expect(ada.stageId).toBe(CONTACTED);
 39	      expect(repository.saved).toHaveLength(1);
 40	    });
 41	
 42	    it('finds the lead by the canonical form of the phone number', async () => {
 43	      const repository = FakeLeadRepository.seededWith(lead('+525512345678', NEW));
 44	      const useCase = new MoveLeadToStage(repository, funnelWith());
 45	
 46	      await useCase.execute({ phone: '+52 (55) 1234-5678', targetStageId: CONTACTED });
 47	
 48	      expect(repository.saved).toHaveLength(1);
 49	    });
 50	  });
 51	
 52	  describe('rule — transitions are open in every direction', () => {
 53	    // MAP.md §3.1 — "Transiciones abiertas. Cualquier etapa existente distinta de
 54	    // la actual - adelante, atras o salto. Incluye salir de `Closed`." The README
 55	    // names exactly one invalid transition (rule 4); there is nothing else to forbid.
 56	    it.each([
 57	      ['forward', NEW, CONTACTED],
 58	      ['skipping a stage', NEW, CLOSED],
 59	      ['backward', QUALIFIED, NEW],
 60	      ['out of the last stage', CLOSED, CONTACTED],
 61	    ])('allows moving %s', async (_label, from, to) => {
 62	      const ada = lead(A_PHONE, from);
 63	      const repository = FakeLeadRepository.seededWith(ada);
 64	      const useCase = new MoveLeadToStage(repository, funnelWith());
 65	
 66	      await useCase.execute({ phone: A_PHONE, targetStageId: to });
 67	
 68	      expect(ada.stageId).toBe(to);
 69	    });
 70	  });
 71	
 72	  describe('rule 2 — the target stage must exist', () => {
 73	    it('rejects a target stage the funnel does not have', async () => {
 74	      const repository = FakeLeadRepository.seededWith(lead(A_PHONE, NEW));
 75	      const useCase = new MoveLeadToStage(repository, funnelWith());
 76	
 77	      await expect(
 78	        useCase.execute({ phone: A_PHONE, targetStageId: 'archived' })
 79	      ).rejects.toThrow(StageNotFoundError);
 80	    });
 81	  });
 82	
 83	  describe('the lead must exist', () => {
 84	    it('rejects a phone number the repository does not know', async () => {
 85	      // MAP.md §3.3 — "Lead inexistente al mover: error de dominio propio
 86	      // (LeadNotFoundError), no reciclar uno existente."
 87	      const repository = new FakeLeadRepository();
 88	      const useCase = new MoveLeadToStage(repository, funnelWith());
 89	
 90	      await expect(
 91	        useCase.execute({ phone: A_PHONE, targetStageId: CONTACTED })
 92	      ).rejects.toThrow(LeadNotFoundError);
 93	    });
 94	  });
 95	
 96	  describe('rule 4 — a lead cannot move to the stage it is already in', () => {
 97	    it('rejects the move', async () => {
 98	      const repository = FakeLeadRepository.seededWith(lead(A_PHONE, CONTACTED));
 99	      const useCase = new MoveLeadToStage(repository, funnelWith());
100	
101	      await expect(
102	        useCase.execute({ phone: A_PHONE, targetStageId: CONTACTED })
103	      ).rejects.toThrow(InvalidStageTransitionError);
104	    });
105	
106	    it('saves nothing', async () => {
107	      const repository = FakeLeadRepository.seededWith(lead(A_PHONE, CONTACTED));
108	      const useCase = new MoveLeadToStage(repository, funnelWith());
109	
110	      await expect(useCase.execute({ phone: A_PHONE, targetStageId: CONTACTED })).rejects.toThrow(InvalidStageTransitionError);
111	      expect(repository.saved).toEqual([]);
112	    });
113	  });
114	
115	  describe('rule 3 — moving into a full stage is rejected', () => {
116	    it('rejects the move when the target stage is at its limit', async () => {
117	      const ada = lead(A_PHONE, NEW);
118	      const repository = FakeLeadRepository.seededWith(ada, lead(ANOTHER_PHONE, QUALIFIED));
119	      const useCase = new MoveLeadToStage(repository, funnelWith({ [QUALIFIED]: 1 }));
