144	    });
145	
146	    it('rejects every move into a stage closed with capacity 0, even an empty one', async () => {
147	      // MAP.md §1 — "`0` = etapa cerrada (no ilimitada)".
148	      const ada = lead(A_PHONE, NEW);
149	      const repository = FakeLeadRepository.seededWith(ada);
150	      const useCase = new MoveLeadToStage(repository, funnelWith({ [CLOSED]: 0 }));
