152	      await expect(useCase.execute({ phone: A_PHONE, targetStageId: CLOSED })).rejects.toThrow(
153	        StageCapacityExceededError
154	      );
155	    });
156	
157	    it('does not treat a capacity of 0 like an absent capacity', async () => {
158	      const ada = lead(A_PHONE, NEW);
159	      const repository = FakeLeadRepository.seededWith(ada);
160	      const useCase = new MoveLeadToStage(repository, funnelWith());
161	
162	      await useCase.execute({ phone: A_PHONE, targetStageId: CLOSED });
163	
164	      expect(ada.stageId).toBe(CLOSED);
165	    });
166	  });
167	
168	  describe('input validation', () => {
169	    it('rejects a malformed phone number', async () => {
170	      const repository = new FakeLeadRepository();
171	      const useCase = new MoveLeadToStage(repository, funnelWith());
172	
173	      await expect(
174	        useCase.execute({ phone: '5512345678', targetStageId: CONTACTED })
175	      ).rejects.toThrow(InvalidPhoneNumberError);
176	    });
177	
178	    it('does not touch the repository when the input is malformed', async () => {
179	      const repository = new FakeLeadRepository();
180	      const useCase = new MoveLeadToStage(repository, funnelWith());
181	
182	      await expect(
183	        useCase.execute({ phone: 'not-a-phone', targetStageId: CONTACTED })
184	      ).rejects.toThrow(InvalidPhoneNumberError);
185	
186	      expect(repository.findByPhoneCalls).toEqual([]);
187	      expect(repository.saved).toEqual([]);
188	    });
189	  });
190	
191	  describe('precedence — MAP.md §4', () => {
192	    it('prefers the phone-number error over the missing-stage error', async () => {
193	      // MAP.md §4: "entrada valida (PhoneNumber) -> etapa destino existe".
194	      const repository = new FakeLeadRepository();
195	      const useCase = new MoveLeadToStage(repository, funnelWith());
196	
197	      await expect(
198	        useCase.execute({ phone: 'not-a-phone', targetStageId: 'archived' })
199	      ).rejects.toThrow(InvalidPhoneNumberError);
200	    });
201	
202	    it('prefers the missing-stage error over the missing-lead error', async () => {
203	      // MAP.md §4: "Por que `StageNotFoundError` va antes que `LeadNotFoundError`:
204	      // el funnel se fija en el constructor y es inmutable en runtime, asi que la
205	      // validez de `targetStageId` es funcion pura de peticion + config; la
206	      // existencia del lead depende del repositorio."
207	      const repository = new FakeLeadRepository();
208	      const useCase = new MoveLeadToStage(repository, funnelWith());
209	
210	      await expect(
211	        useCase.execute({ phone: A_PHONE, targetStageId: 'archived' })
212	      ).rejects.toThrow(StageNotFoundError);
213	    });
214	
215	    it('does not consult the repository for a stage the funnel does not have', async () => {
