  1	import { InMemoryLeadRepository } from '../../src/infrastructure/persistence/InMemoryLeadRepository';
  2	import { ANOTHER_PHONE, A_PHONE, CONTACTED, NEW, lead } from '../helpers/factories';
  3	
  4	/**
  5	 * MAP.md §7 — "InMemoryLeadRepository: `Map` indexado por el string canonico del
  6	 * `PhoneNumber`" and "findByPhone devuelve `Lead | null` - null, no undefined".
  7	 *
  8	 * MAP.md §0 — "`save` es el unico camino de escritura => upsert por identidad".
  9	 *
 10	 * These call `findByPhone` with the canonical string, which is what the port
 11	 * declares today (LeadRepository.ts:10). MAP.md §7 says that parameter becomes a
 12	 * `PhoneNumber`; when it does, these call sites pass `phone` instead of
 13	 * `phone.value`. See the notes at the end of the session.
 14	 */
 15	describe('InMemoryLeadRepository', () => {
 16	  describe('save and findByPhone', () => {
 17	    it('finds a saved lead by its phone number', async () => {
 18	      const repository = new InMemoryLeadRepository();
 19	      const ada = lead(A_PHONE, NEW);
 20	
 21	      await repository.save(ada);
 22	
 23	      expect(await repository.findByPhone(ada.phone.value)).toBe(ada);
 24	    });
 25	
 26	    it('returns null for a phone number it does not hold', async () => {
 27	      const repository = new InMemoryLeadRepository();
 28	
 29	      expect(await repository.findByPhone(A_PHONE)).toBeNull();
 30	    });
 31	
 32	    it('is an upsert: saving the same identity twice keeps one lead', async () => {
 33	      const repository = new InMemoryLeadRepository();
 34	      const first = lead(A_PHONE, NEW, 'Ada');
 35	      const second = lead(A_PHONE, CONTACTED, 'Ada Lovelace');
 36	
 37	      await repository.save(first);
 38	      await repository.save(second);
 39	
 40	      expect(await repository.findByPhone(A_PHONE)).toBe(second);
 41	      expect(await repository.findByStage(NEW)).toEqual([]);
 42	    });
 43	
 44	    it('indexes by the canonical string, so presentation does not create a second entry', async () => {
 45	      const repository = new InMemoryLeadRepository();
 46	
 47	      await repository.save(lead('+52 55 1234-5678', NEW));
 48	
 49	      expect(await repository.findByPhone('+525512345678')).not.toBeNull();
 50	    });
 51	
 52	    it('keeps distinct phone numbers apart', async () => {
 53	      const repository = new InMemoryLeadRepository();
 54	      const ada = lead(A_PHONE, NEW);
 55	      const grace = lead(ANOTHER_PHONE, NEW);
 56	
 57	      await repository.save(ada);
 58	      await repository.save(grace);
 59	
 60	      expect(await repository.findByPhone(ANOTHER_PHONE)).toBe(grace);
 61	    });
 62	  });
 63	
 64	  describe('findByStage', () => {
 65	    it('returns an empty array for a stage with no leads', async () => {
 66	      expect(await new InMemoryLeadRepository().findByStage(NEW)).toEqual([]);
 67	    });
 68	
 69	    it('returns only the leads sitting in that stage', async () => {
 70	      const repository = new InMemoryLeadRepository();
 71	      await repository.save(lead(A_PHONE, NEW));
 72	      await repository.save(lead(ANOTHER_PHONE, CONTACTED));
 73	
 74	      const inNew = await repository.findByStage(NEW);
 75	
 76	      expect(inNew.map((entry) => entry.phone.value)).toEqual([A_PHONE]);
 77	    });
 78	
 79	    it('reflects a lead that moved, once it is saved again', async () => {
 80	      const repository = new InMemoryLeadRepository();
 81	      const ada = lead(A_PHONE, NEW);
 82	      await repository.save(ada);
 83	
 84	      ada.moveTo(CONTACTED);
 85	      await repository.save(ada);
 86	
 87	      expect(await repository.findByStage(NEW)).toEqual([]);
 88	      expect(await repository.findByStage(CONTACTED)).toHaveLength(1);
 89	    });
 90	
 91	    it('is what the capacity check counts: occupancy is derived, never stored', async () => {
 92	      // MAP.md §0 — "La ocupacion se calcula (`findByStage().length`), no se
 93	      // almacena", which is why the port needs this method at all (MAP.md §2).
 94	      const repository = new InMemoryLeadRepository();
 95	      await repository.save(lead(A_PHONE, NEW));
 96	      await repository.save(lead(ANOTHER_PHONE, NEW));
 97	
 98	      expect((await repository.findByStage(NEW)).length).toBe(2);
 99	    });
100	  });
101	});

