  1	import { PhoneNumber } from '../../src/domain/value-objects/PhoneNumber';
  2	import { InvalidPhoneNumberError } from '../../src/domain/errors/InvalidPhoneNumberError';
  3	
  4	/**
  5	 * MAP.md §1 — "Acepta: `+` seguido de 8-15 digitos, ignorando separadores:
  6	 * espacios, guiones, parentesis y puntos. Rechaza: todo lo demas."
  7	 *
  8	 * MAP.md §1 — "normalizamos presentacion, nunca inferimos semantica."
  9	 */
 10	describe('PhoneNumber', () => {
 11	  describe('accepted format: "+" followed by 8 to 15 digits', () => {
 12	    it('accepts the shortest accepted length (8 digits)', () => {
 13	      expect(new PhoneNumber('+12345678').value).toBe('+12345678');
 14	    });
 15	
 16	    it('accepts the longest accepted length (15 digits)', () => {
 17	      expect(new PhoneNumber('+123456789012345').value).toBe('+123456789012345');
 18	    });
 19	
 20	    it('rejects one digit below the lower bound', () => {
 21	      expect(() => new PhoneNumber('+1234567')).toThrow(InvalidPhoneNumberError);
 22	    });
 23	
 24	    it('rejects one digit above the upper bound', () => {
 25	      expect(() => new PhoneNumber('+1234567890123456')).toThrow(InvalidPhoneNumberError);
 26	    });
 27	  });
 28	
 29	  describe('separators are presentation, not data', () => {
 30	    it.each([
 31	      ['spaces', '+52 55 1234 5678'],
 32	      ['dashes', '+52-55-1234-5678'],
 33	      ['parentheses', '+52(55)12345678'],
 34	      ['dots', '+52.55.1234.5678'],
 35	      ['a mix of all of them', '+52 (55) 1234-5678'],
 36	    ])('ignores %s', (_label, input) => {
 37	      expect(new PhoneNumber(input).value).toBe('+525512345678');
 38	    });
 39	
 40	    it('produces a canonical form with no separators left in it', () => {
 41	      expect(new PhoneNumber('+52 (55) 1234-5678').value).toBe('+525512345678');
 42	    });
 43	
 44	    it('counts digits after removing separators, not before', () => {
 45	      // 8 digits written across separators is still 8 digits.
 46	      expect(new PhoneNumber('+1 234-5678').value).toBe('+12345678');
 47	    });
 48	  });
 49	
 50	  describe('rejected input', () => {
 51	    it.each([
 52	      ['no country code', '5512345678'],
 53	      ['a leading zero instead of "+"', '005512345678'],
 54	      ['letters', '+52-CALL-NOW'],
 55	      ['an extension', '+525512345678 ext 3'],
 56	      ['an empty string', ''],
 57	      ['only a plus sign', '+'],
 58	      ['only separators', '   '],
 59	      ['a plus that is not leading', '52+5512345678'],
 60	    ])('rejects %s', (_label, input) => {
 61	      expect(() => new PhoneNumber(input)).toThrow(InvalidPhoneNumberError);
 62	    });
 63	
 64	    it('names the rejected input in the error, so the caller can see what failed', () => {
 65	      expect(() => new PhoneNumber('5512345678')).toThrow(/5512345678/);
 66	    });
 67	  });
 68	
 69	  describe('identity', () => {
 70	    it('treats two presentations of the same number as equal', () => {
 71	      // MAP.md §9 — "identidad: `+52 55 1234 5678` y `+525512345678` son el mismo lead"
 72	      expect(new PhoneNumber('+52 55 1234 5678').equals(new PhoneNumber('+525512345678'))).toBe(
 73	        true
 74	      );
 75	    });
 76	
 77	    it('treats different digits as different numbers', () => {
 78	      expect(new PhoneNumber('+525512345678').equals(new PhoneNumber('+525587654321'))).toBe(false);
 79	    });
 80	
 81	    it('does not unify numbers that differ in their digits, only in their separators', () => {
 82	      // MAP.md §1 — the `521` case: "ahi la diferencia esta en los digitos, no en la
 83	      // presentacion", and unifying them would require inferring that the `1` is a
 84	      // Mexican mobile prefix. Presentation is normalised; meaning is never inferred.
 85	      expect(new PhoneNumber('+5215512345678').equals(new PhoneNumber('+525512345678'))).toBe(
 86	        false
 87	      );
 88	    });
 89	
 90	    it('exposes the canonical form through toString', () => {
 91	      expect(String(new PhoneNumber('+52 55 1234 5678'))).toBe('+525512345678');
 92	    });
 93	  });
 94	});
  1	import { Lead } from '../../src/domain/entities/Lead';
  2	import { InvalidLeadError } from '../../src/domain/errors/InvalidLeadError';
  3	import { InvalidStageTransitionError } from '../../src/domain/errors/InvalidStageTransitionError';
  4	import { CONTACTED, NEW, phone } from '../helpers/factories';
  5	
  6	/**
  7	 * MAP.md §2 — the only invariants the lead can hold on its own are the ones that
  8	 * depend on nothing but its own state: a non-empty name, and "Destino != actual"
  9	 * inside `moveTo()`. Everything else (the stage existing, the stage having room)
 10	 * belongs to the funnel or to the use case.
 11	 */
 12	describe('Lead', () => {
 13	  describe('name', () => {
 14	    it('rejects an empty name', () => {
 15	      expect(() => new Lead(phone(), '', NEW)).toThrow(InvalidLeadError);
 16	    });
 17	
 18	    it('rejects a name made only of whitespace', () => {
 19	      expect(() => new Lead(phone(), '   ', NEW)).toThrow(InvalidLeadError);
 20	    });
 21	
 22	    it('accepts a name with content', () => {
 23	      expect(new Lead(phone(), 'Ada', NEW).name).toBe('Ada');
 24	    });
 25	  });
 26	
 27	  describe('stage', () => {
 28	    it('starts at the stage it was constructed with', () => {
 29	      expect(new Lead(phone(), 'Ada', NEW).stageId).toBe(NEW);
 30	    });
 31	
 32	    it('moves to a different stage', () => {
 33	      const lead = new Lead(phone(), 'Ada', NEW);
 34	
 35	      lead.moveTo(CONTACTED);
 36	
 37	      expect(lead.stageId).toBe(CONTACTED);
 38	    });
 39	
 40	    it('rejects a move to the stage it is already in', () => {
 41	      // MAP.md §2 — "Destino != actual | Lead.moveTo() | depende solo del estado
 42	      // del propio lead".
 43	      const lead = new Lead(phone(), 'Ada', NEW);
 44	
 45	      expect(() => lead.moveTo(NEW)).toThrow(InvalidStageTransitionError);
 46	    });
 47	
 48	    it('stays in its stage when the move is rejected', () => {
 49	      const lead = new Lead(phone(), 'Ada', NEW);
 50	
 51	      expect(() => lead.moveTo(NEW)).toThrow(InvalidStageTransitionError);
 52	      expect(lead.stageId).toBe(NEW);
 53	    });
 54	
 55	    it('reports both ends of the rejected transition in the error message', () => {
 56	      // MAP.md §3 — "una transicion es una relacion binaria - origen y destino.
 57	      // `InvalidStageTransitionError(stageId)` no podria decir de donde venia el lead."
 58	      const lead = new Lead(phone(), 'Ada', NEW);
 59	      lead.moveTo(CONTACTED);
 60	
 61	      expect(() => lead.moveTo(CONTACTED)).toThrow(
 62	        expect.objectContaining({ message: expect.stringContaining(CONTACTED) })
 63	      );
 64	    });
 65	
 66	    it('does not police whether the target stage exists in any funnel', () => {
 67	      // MAP.md §2 — "La etapa destino existe | Funnel | unico que conoce su
 68	      // configuracion". The lead holds a stageId, not a reference to a Stage, so
 69	      // it cannot and must not answer this.
 70	      const lead = new Lead(phone(), 'Ada', NEW);
 71	
 72	      lead.moveTo('a-stage-no-funnel-has');
 73	
 74	      expect(lead.stageId).toBe('a-stage-no-funnel-has');
 75	    });
 76	  });
 77	
 78	  describe('isAt', () => {
 79	    it('is true for the stage the lead sits in', () => {
 80	      expect(new Lead(phone(), 'Ada', NEW).isAt(NEW)).toBe(true);
 81	    });
 82	
 83	    it('is false for any other stage', () => {
 84	      expect(new Lead(phone(), 'Ada', NEW).isAt(CONTACTED)).toBe(false);
 85	    });
 86	
 87	    it('is a pure query: it neither throws nor moves the lead', () => {
 88	      // MAP.md §2 — "Lead.isAt(stageId): boolean - consulta pura, sin regla dentro."
 89	      // This is what lets the use case ask "same stage?" before deciding which
 90	      // error wins, without mutating anything.
 91	      const lead = new Lead(phone(), 'Ada', NEW);
 92	
 93	      expect(() => lead.isAt(NEW)).not.toThrow();
 94	      expect(lead.stageId).toBe(NEW);
 95	    });
 96	  });
 97	});
  1	import { Funnel, Stage } from '../../src/domain/entities/Funnel';
  2	import { InvalidFunnelError } from '../../src/domain/errors/InvalidFunnelError';
  3	import { StageNotFoundError } from '../../src/domain/errors/StageNotFoundError';
  4	import { CLOSED, CONTACTED, NEW, QUALIFIED, funnelWith } from '../helpers/factories';
  5	
  6	/**
  7	 * MAP.md §1 — "Valida al construirse -> InvalidFunnelError: >=1 etapa; ids no
  8	 * vacios y unicos; capacity entera >= 0 si esta presente."
  9	 *
 10	 * MAP.md §3.2 — "Capacidad: ausente = sin tope . `0` = etapa cerrada .
 11	 * negativa/no entera = funnel invalido."
 12	 */
 13	describe('Funnel', () => {
 14	  describe('construction', () => {
 15	    it('rejects a funnel with no stages', () => {
 16	      expect(() => new Funnel('f', [])).toThrow(InvalidFunnelError);
 17	    });
 18	
 19	    it('rejects an empty stage id', () => {
 20	      expect(() => new Funnel('f', [{ id: '', name: 'New' }])).toThrow(InvalidFunnelError);
 21	    });
 22	
 23	    it('rejects a stage id made only of whitespace', () => {
 24	      expect(() => new Funnel('f', [{ id: '   ', name: 'New' }])).toThrow(InvalidFunnelError);
 25	    });
 26	
 27	    it('rejects duplicated stage ids', () => {
 28	      expect(
 29	        () =>
 30	          new Funnel('f', [
 31	            { id: NEW, name: 'New' },
 32	            { id: NEW, name: 'New again' },
 33	          ])
 34	      ).toThrow(InvalidFunnelError);
 35	    });
 36	
 37	    it('rejects a negative capacity', () => {
 38	      expect(() => new Funnel('f', [{ id: NEW, name: 'New', capacity: -1 }])).toThrow(
 39	        InvalidFunnelError
 40	      );
 41	    });
 42	
 43	    it('rejects a non-integer capacity', () => {
 44	      expect(() => new Funnel('f', [{ id: NEW, name: 'New', capacity: 1.5 }])).toThrow(
 45	        InvalidFunnelError
 46	      );
 47	    });
 48	
 49	    it('accepts an absent capacity', () => {
 50	      expect(() => new Funnel('f', [{ id: NEW, name: 'New' }])).not.toThrow();
 51	    });
 52	
 53	    it('accepts a capacity of zero, because zero is a closed stage and not an invalid one', () => {
 54	      expect(() => new Funnel('f', [{ id: NEW, name: 'New', capacity: 0 }])).not.toThrow();
 55	    });
 56	
 57	    it('names the failing cause in the error, not just the funnel', () => {
 58	      // MAP.md §3 — "con el id de un funnel en la mano no se sabe si fallo por no
 59	      // tener etapas, por ids duplicados o por una capacity invalida".
 60	      expect(() => new Funnel('f', [])).toThrow(/stage/i);
 61	    });
 62	
 63	    it('is not affected by mutating the stages passed in after construction', () => {
 64	      // Funnel.ts:53-55 — the stages are copied so that "mutating the array or the
 65	      // stage objects after construction cannot change a funnel that has already
 66	      // been validated".
 67	      const stages: Stage[] = [{ id: NEW, name: 'New', capacity: 1 }];
 68	      const funnel = new Funnel('f', stages);
 69	
 70	      stages[0].capacity = 99;
 71	      stages.push({ id: 'smuggled', name: 'Smuggled' });
 72	
 73	      expect(funnel.canAcceptOneMore(NEW, 1)).toBe(false);
 74	      expect(funnel.hasStage('smuggled')).toBe(false);
 75	    });
 76	  });
 77	
 78	  describe('stages', () => {
 79	    it('reports the first stage, which is where new leads enter', () => {
 80	      expect(funnelWith().firstStageId()).toBe(NEW);
 81	    });
 82	
 83	    it('takes stage order from the array position', () => {
 84	      // MAP.md §0 — "Orden de etapas = posicion en el array; sin campo `order`".
 85	      const funnel = new Funnel('f', [
 86	        { id: CLOSED, name: 'Closed' },
 87	        { id: NEW, name: 'New' },
 88	      ]);
 89	
 90	      expect(funnel.firstStageId()).toBe(CLOSED);
 91	    });
 92	
 93	    it('knows which stages it has', () => {
 94	      const funnel = funnelWith();
 95	
 96	      expect(funnel.hasStage(QUALIFIED)).toBe(true);
 97	      expect(funnel.hasStage('nope')).toBe(false);
 98	    });
 99	
100	    it('exposes the name of a stage', () => {
101	      expect(funnelWith().stageName(CONTACTED)).toBe('Contacted');
102	    });
103	
104	    it('rejects a question about a stage it does not have', () => {
105	      expect(() => funnelWith().stageName('nope')).toThrow(StageNotFoundError);
106	      expect(() => funnelWith().canAcceptOneMore('nope', 0)).toThrow(StageNotFoundError);
107	    });
108	  });
109	
110	  describe('capacity', () => {
111	    it('accepts one more lead when the stage has no limit, however full it is', () => {
112	      expect(funnelWith().canAcceptOneMore(NEW, 10_000)).toBe(true);
113	    });
114	
115	    it('accepts one more lead while the occupancy is below the limit', () => {
116	      expect(funnelWith({ [QUALIFIED]: 2 }).canAcceptOneMore(QUALIFIED, 1)).toBe(true);
117	    });
118	
119	    it('refuses one more lead once the occupancy reaches the limit', () => {
120	      expect(funnelWith({ [QUALIFIED]: 2 }).canAcceptOneMore(QUALIFIED, 2)).toBe(false);
121	    });
122	
123	    it('refuses one more lead when the occupancy is somehow above the limit', () => {
124	      expect(funnelWith({ [QUALIFIED]: 2 }).canAcceptOneMore(QUALIFIED, 3)).toBe(false);
125	    });
126	
127	    describe('capacity: 0 means the stage is closed, not unlimited', () => {
128	      // MAP.md §1 — "Semantica de `capacity`: `undefined` = sin tope; `0` = etapa
129	      // cerrada (no ilimitada)". And the trap this guards against, verbatim:
130	      // "el tipo es `number | undefined` y `strict` no protege contra
131	      // `if (stage.capacity && ...)`, que trataria `0` como ilimitado."
132	      it('refuses a lead even when the stage is empty', () => {
133	        expect(funnelWith({ [QUALIFIED]: 0 }).canAcceptOneMore(QUALIFIED, 0)).toBe(false);
134	      });
135	
136	      it('does not behave like an absent capacity', () => {
137	        const closed = funnelWith({ [QUALIFIED]: 0 });
138	        const unlimited = funnelWith();
139	
140	        expect(closed.canAcceptOneMore(QUALIFIED, 0)).toBe(false);
141	        expect(unlimited.canAcceptOneMore(QUALIFIED, 0)).toBe(true);
142	      });
143	    });
144	  });
145	});

