 * (`findByStage().length`) because it is never stored.
 */
export interface LeadRepository {
  save(lead: Lead): Promise<void>;
  findByPhone(phone: PhoneNumber): Promise<Lead | null>;
  findByStage(stageId: string): Promise<Lead[]>;
}
